  onOpen: () => void; ar: boolean; source: string; mediaKind: 'audio' | 'video'; title: string; duration: number; playhead: number; start: number; end: number;
  value: StudioEdits; onChange: (value: StudioEdits) => void; capture: () => unknown; restore: (value: unknown) => void;
  openProject: (project: PortableProject) => Promise<void>; payload: (range?: NamedRange) => unknown;
  onSeek: (seconds: number) => void; onCuts: (cuts: {startSeconds:number;endSeconds:number}[]) => void;
  cues: readonly EditorSubtitleCue[]; onCues: (cues: readonly EditorSubtitleCue[]) => void;
  transcript?: Transcript; onTranscript: (value: Transcript) => void; onProxy: (path: string) => Promise<void>;
  onImportTranscript: (value: Transcript) => void;
  onReviewCaptions: (video: boolean) => void;
