        if(index<0)return;
        const delta=event.key==='ArrowRight'?(p.ar?-1:1):event.key==='ArrowLeft'?(p.ar?1:-1):0;
        const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:delta?(index+delta+tabs.length)%tabs.length:-1;
